import { getUUID } from './utils';
export const convertListToSelectList = (options, _icon = '', showIcon = false) => {
    return options.reduce((acc, currentElement) => {
        let id, selectedText, name, value, icon;
        if (typeof currentElement === 'string') {
            id = getUUID();
            selectedText = currentElement;
            name = currentElement;
            value = currentElement;
            icon = _icon;
        }
        else {
            ({ id, selectedText, name, value, icon } = currentElement);
        }
        if (!icon && showIcon && !!_icon)
            icon = _icon;
        return [
            ...acc,
            {
                idItem: id,
                selectedText: selectedText || name,
                text: name,
                value,
                icon,
            },
        ];
    }, []);
};
const getValue = (controlValue, componentValue, isMultiSelect) => {
    if (Array.isArray(controlValue) || Array.isArray(componentValue)) {
        if (isMultiSelect) {
            if (Array.isArray(controlValue) && !!controlValue.length)
                return controlValue;
            else
                return componentValue;
        }
        return '';
    }
    return controlValue || componentValue;
};
export const getValidInitialValues = (controlValue, componentValue, list, isMultiSelect) => {
    const value = getValue(controlValue, componentValue, isMultiSelect);
    if (!!value) {
        const options = list.reduce((accumulator, currentElement) => [
            ...accumulator,
            typeof currentElement === 'string'
                ? currentElement
                : currentElement.value,
        ], []);
        if (isMultiSelect) {
            if (Array.isArray(value) && !!value.length)
                return value.filter((element) => options.includes(element));
            if (typeof value === 'string' && options.includes(value))
                return [value];
        }
        if (Array.isArray(value))
            return '';
        if (typeof value === 'string' && options.includes(value))
            return value;
    }
    if (isMultiSelect)
        return [];
    return '';
};
export const getSelectedValues = (controlValue, value) => {
    if (!!controlValue) {
        if (controlValue.includes(value)) {
            return controlValue.reduce((acc, currentValue) => {
                if (currentValue === value)
                    return acc;
                else
                    return [...acc, currentValue];
            }, []);
        }
        return [...controlValue, value];
    }
    return [value];
};
export const filteredValue = (value, list) => {
    if (!!value) {
        return list.filter((item) => item.text.toLowerCase().includes(value.toLowerCase()));
    }
    return list;
};
